// Update room light pulse using light map + sin table; reset when level changes or timer ends.
void __stdcall ClientLight_UpdateRoomLightPulse() {
    int nFadeOutBase;
    float fVar1;
    float fAmbientColorF;
    uint32_t nAmbientArg = 0;
    uint8_t* pBlue = &gRoomLightPulse.nLightRoomBlue;
    uint8_t* pGreen = &gRoomLightPulse.nLightRoomGreen;
    uint8_t* pRed = &gRoomLightPulse.nLightRoomRed;
    uint32_t nAmbientColor = 0;
    D2RoomStrc* pRoom = UNIT::CUnit::GetCurrentRoom();
    Draw::LightMap::ROOM_GetAmbientLightColor(pRoom, &nAmbientColor, (char*)pRed, (char*)pGreen, (char*)pBlue, nAmbientArg);
    if ((int)gRoomLightPulse.nCurrentTick < (int)gRoomLightPulse.nFadeInDuration) {
      fVar1 = Fog::MATH_sinTable_f32_LookupOffset(gRoomLightPulse.nSinOffset);
      fAmbientColorF = (float)(int)nAmbientColor;
      if ((int)nAmbientColor < 0) {
        fAmbientColorF += 4.2949673e+09;
      }

      gRoomLightPulse.nLightPulseIntensity = (uint32_t)(fAmbientColorF * fVar1);
      gRoomLightPulse.nSinOffset = (int)(gRoomLightPulse.nCurrentTick << 7) / (int)gRoomLightPulse.nFadeInDuration;
    } else if (!((int)gRoomLightPulse.nCurrentTick < (int)(gRoomLightPulse.nTotalDuration - gRoomLightPulse.nFadeOutDuration))) {
      fVar1 = Fog::MATH_sinTable_f32_LookupOffset(gRoomLightPulse.nSinOffset);
      fAmbientColorF = (float)(int)nAmbientColor;
      if ((int)nAmbientColor < 0) {
        fAmbientColorF += 4.2949673e+09;
      }

      gRoomLightPulse.nLightPulseIntensity = (uint32_t)(fAmbientColorF * fVar1);
      nFadeOutBase = gRoomLightPulse.nFadeOutDuration - gRoomLightPulse.nTotalDuration;
      if (!gRoomLightPulse.nFadeOutDuration) {
        gRoomLightPulse.nFadeOutDuration = 0x19;
      }

      gRoomLightPulse.nSinOffset = 0x80 - (int)((nFadeOutBase + gRoomLightPulse.nCurrentTick) * 0x80) / (int)gRoomLightPulse.nFadeOutDuration;
    } else {
      gRoomLightPulse.nLightPulseIntensity = 0;
    }

    gRoomLightPulse.nCurrentTick++;
    pRoom = UNIT::CUnit::GetCurrentRoom();
    eD2LevelId eLevelId = LEVEL_None;
    if (pRoom) {
      eLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
    }
    if (!((int)gRoomLightPulse.nCurrentTick > (int)gRoomLightPulse.nTotalDuration || eLevelId != gRoomLightPulse.eLevelId)) {
      return;
    }

    memset(&gRoomLightPulse, 0, 0x2c);
}

