      dSeedResult = D2_SEED_NEXT(*pSeed);
      pSeed->nSeedHigh = dSeedResult.nSeedHigh;
      pSeed->nSeedLow = dSeedResult.nSeedLow;
      return (int)(dSeedResult.nSeedLow % nRangeWidth) + nMin;
