// Guard on a non-zero global deadline; sample the
// tick counter; clear the deadline once passed; otherwise compute remaining = deadline - now, height =
// ScreenY - 0x2f, adjust the horizontal span by half the screen width on border type 1 versus 2, and
// issue one solid-rect blit with colour 0 and alpha (remaining * 0xff) / 500. The 0x2f inset, the
// border-type 1/2 split and the /500 alpha ramp are the identifying constants. Position in ViewDraw2
// confirms it: the final call of the pass.
// @wasnamed DRAW_WORLD_FadeEffectJustWarped
// Draws the post-warp black fade-out over the play area, ramping alpha down over 500 ms.
void __stdcall dSceneTransitionDraw() {
    int32_t nXStart = 0;
    if (!gdwWarpFadeExpireTime) {
      return;
    }

    DWORD dwTickCount = GetTickCount();
    int nXEnd = ScreenSizeX;
    if (dwTickCount > gdwWarpFadeExpireTime) {
      gdwWarpFadeExpireTime = 0;
      return;
    }

    int nTimeRemaining = gdwWarpFadeExpireTime - dwTickCount;
    int nYEnd = ScreenSizeY - 0x2f;
    uint32_t nBorderType = UI::Path::DRAW_GetTypeOfBorder();
    switch (nBorderType) {
      case 1:
        {
          nXEnd -= ScreenSizeX / 2;
          break;
        }
      case 2:
        {
          nXStart = ScreenSizeX / 2;
          break;
        }
    }

    D2gfx::D2GFX::D2GFX_DrawSolidRectAlpha(nXStart, 0, nXEnd, nYEnd, 0, nTimeRemaining * 0xff / 500);
}

