// RC4 key schedule: fills pRc4State's 256-byte S-box with 0..255, zeroes the i/j bytes at +0x100/+0x101, then swaps S[i] with S[j], j += S[i] + pKey[i % nKeyLength].
// The only caller, WARDEN_DecryptAndLoadModule, passes a 0x10-byte key; 1.14d asm 004e09c0..004e0a1a.
void __thiscall WARDEN_RC4Init(D2RC4StateStrc * pRc4State, uint8_t * pKey, uint32_t nKeyLength) {
    uint32_t nNextIdx;
    uint32_t nKeyIdx = 0;
    uint32_t nByteIdx = 0;
    do {
      pRc4State->sbox[nByteIdx] = (uint8_t)nByteIdx;
      nByteIdx++;
    } while (nByteIdx < 0x100);

    uint8_t bySwapIndex = 0;
    pRc4State->nIndexI = 0;
    pRc4State->nIndexJ = 0;
    nByteIdx = 0;
    do {
      uint8_t bySwapTemp;
      nNextIdx = nByteIdx + 1;
      bySwapIndex = bySwapIndex + pKey[(uint8_t)nKeyIdx] + pRc4State->sbox[nByteIdx];
      bySwapTemp = pRc4State->sbox[nByteIdx];
      pRc4State->sbox[nByteIdx] = pRc4State->sbox[bySwapIndex];
      pRc4State->sbox[bySwapIndex] = bySwapTemp;
      nKeyIdx = ((nKeyIdx & 0xff) + 1) % nKeyLength;
      nByteIdx = nNextIdx;
    } while (nNextIdx < 0x100);
}

